ProjectALife.DialogueShards["scenes_plan_6"] = {
{"fw_ld5_jailplan_f069","plan",2,"reg=prison|day=2,30|mood=calm",{1,"We need a leader, somebody who's been out",2,"Who the hell's been out?",1,"Nobody, we're all in the same boat",2,"We take turns, one day each, whoever screws up gets voted off"}},
{"fw_ld5_jailplan_f070","plan",2,"reg=prison|mood=calm",{1,"We rob the clinic, painkillers, we trade 'em",2,"Trade with who?",1,"Anybody, a pill's worth more than a can of beans",2,"If it's a pill that works, we keep half, I got a bad back"}},
{"fw_ld5_jailplan_f071","plan",2,"reg=prison|hour=19,4|mood=grim",{1,"We don't sleep in the same place twice, that's how they catch you",2,"Who's they?",1,"Everybody, the ones in uniforms, the ones without",2,"I'll sleep with one eye open, I did it for six years, shit"}},
{"fw_ld5_jailplan_f072","plan",2,"reg=prison|day=3,40|mood=funny",{1,"I'm hungry",2,"We're all hungry, we ate yesterday",1,"I ate half yesterday, you ate the other half",2,"It was a good half"}},
{"fw_ld5_outplan_f073","plan",2,"reg=outlaw|day=2,30|mood=calm",{1,"Camp's in the old barn, nobody's been there since the spring",2,"What about the owner?",1,"Gone, I checked, left a note, said back in a week, two years ago",2,"Good, a barn that's been abandoned, I like it"}},
{"fw_ld5_outplan_f074","plan",2,"reg=outlaw|day=2,30|mood=calm",{1,"We trade with the farmers, eggs for a rifle cartridge, milk for a pair of boots",2,"They don't like us",1,"Don't matter, nobody turns down boots",2,"I'm learning to love the boots"}},
{"fw_ld5_outplan_f075","plan",2,"reg=outlaw|day=3,30|mood=grim",{1,"Army's looking for deserters, I heard it on a radio",2,"Radio's been dead a week, shit",1,"Somebody's got a radio, that's what I'm saying, somebody's listening",2,"We move camp, we stay a step ahead, we're a moving target"}},
{"fw_ld5_outplan_f076","plan",2,"reg=outlaw|day=3,30|mood=calm",{1,"There's a quarry up the road, steep walls, one entrance, I'd sleep there",2,"Is there water?",1,"A pond at the bottom, clean, I checked, I drank it, I'm still alive",2,"That's the best endorsement I've heard"}},
{"fw_ld5_outplan_f077","plan",2,"reg=outlaw|day=2,30|mood=funny",{1,"What are we doing?",2,"Don't die",1,"And after that?",2,"Don't die AGAIN, I'm pretty simple"}},
{"fw_ld5_outplan_f078","plan",2,"reg=outlaw|mood=sad",{1,"You ever think about going home?",2,"Home's a house in Ohio with a woman who doesn't want me",1,"Maybe she does now",2,"She's got a lot of other things to want, I'll stay out here, thanks"}},
{"fw_ld5_outplan_f079","plan",2,"reg=outlaw|hour=5,12|mood=calm",{1,"We move at first light, I want to be at the creek before noon",2,"Why the goddamn creek?",1,"Water, fish, a place to wash, I'm sick of smelling like me",2,"I'm sick of smelling like you too, let's go"}},
{"fw_ld5_outplan_f080","plan",2,"reg=outlaw|day=3,30|mood=calm",{1,"There's a church up the hill with a bell, we could ring it",2,"For what?",1,"Signal, the others'd know where we are, the ones that are left",2,"Or the wrong people'd know, I say we don't ring the bell"}},
{"fw_ld5_crew_f081","plan",2,"r1=gang|r2=club|mood=calm",{1,"You guys got bikes, we got a truck, we take the supermarket together",2,"What the hell do we get out of it?",1,"Half of everything, and you don't have to push your bikes",2,"Half, fine, but I drive, I don't trust anyone else with a truck"}},
{"fw_ld5_crew_f082","plan",2,"r1=club|r2=prison|day=2,30|mood=calm",{1,"You're the new guys, you're on lookout",2,"We just got here",1,"That's why, nobody trusts you, and nobody should, stand at the corner",2,"Fine, but when you want us to do something real, ask us nice"}},
{"fw_ld5_crew_f083","plan",2,"r1=prison|r2=crime|mood=calm",{1,"You got a boss, we got a plan, we take the warehouse together",2,"What warehouse?",1,"The one by the tracks, it's got boxes, I'm told the boxes have stuff in 'em",2,"I like a man who has a plan with boxes, I'll tell the boss"}},
{"fw_ld5_crew_f084","plan",2,"r1=crime|r2=raider|mood=calm",{1,"We're a business, you're a crew, you work for us",2,"We work for nobody",1,"You work for a share, that's different, I'll explain it slowly",2,"Explain it fast, I'm hungry"}},
{"fw_ld5_crew_f085","plan",3,"r1=raider|r2=prison|r3=gang|mood=funny",{1,"Three crews, one truck, who drives?",2,"I do, I'm the best driver",3,"You're the worst driver, I was in the back last time",1,"I drive, I'm the one with the keys",2,"You have the keys because you stole 'em from me",3,"Everybody shut the fuck up, we're late"}},
{"fw_ld5_gangplan_f086","plan",2,"reg=gang|mood=calm",{1,"We got a radio, but it's all static",2,"Who knows how to use it?",1,"The old guys got a ham radio somewhere, a case of beer buys us a teacher",2,"A teacher for a case of beer, I like it, I'm in"}},
{"fw_ld5_gangplan_f087","plan",2,"reg=gang|mood=funny",{1,"We hold the store and charge a can to get in",2,"That's a toll",1,"It's a membership fee, I read about it",2,"Where'd you read about it?",1,"On a cereal box, shut up"}},
{"fw_ld5_gangplan_f088","plan",2,"reg=gang|mood=calm",{1,"We need boots, mine are coming apart",2,"Shoe store on Fifth",1,"It's picked over, I looked, but there's always a box in the back nobody thinks of",2,"There's always a box, I'll go with you, I need socks too"}},
{"fw_ld5_gangplan_f089","plan",2,"reg=gang|day=2,30|mood=funny",{1,"East side's got a plan, and we got no plan",2,"So?",1,"So we do what they do, only a day later",2,"That's the dumbest plan I ever heard, and it's the best one we got"}},
{"fw_ld5_clubplan_f090","plan",2,"reg=club|hour=4,12|mood=calm",{1,"We ride out at dawn, fuel check, tires, chains, nobody leaves without his lid",2,"Where to?",1,"The lake cabin, thirty miles, we got a road, we got a roof",2,"I got a bad feeling about the road, but I'll ride it"}},
{"fw_ld5_clubplan_f091","plan",2,"reg=club|mood=calm",{1,"Skeeter's bike's dead, the chain snapped",2,"Tow him",1,"With what?",2,"A chain, a rope, my fucking bike, I don't care, we don't leave a brother on the road"}},
{"fw_ld5_clubplan_f092","plan",2,"reg=club|mood=angry",{1,"Turn the fucking pipes down, they're too loud, the noise draws 'em",2,"They're loud pipes, that's what they're for",1,"Not anymore, you hear that? Not anymore",2,"...Fine, I'll stuff a rag in the pipe, Christ, it's like cutting off my arm"}},
{"fw_ld5_clubplan_f093","plan",2,"reg=club|mood=calm",{1,"We make a run to the river, fill the water cans, back by supper",2,"Who's riding bitch?",1,"The prospect, he's good for one thing",2,"Hold on tight, prospect, I take the curves fast"}},
{"fw_ld5_crmplan_f094","plan",2,"reg=crime|day=2,30|mood=calm",{1,"Inventory: two hundred cans, forty gallons, fourteen rifles, three cartons",2,"That's not a lot",1,"It's enough if nobody's stupid, and we're not stupid",2,"We got Donnie, he's stupid, but he's loyal"}},
{"fw_ld5_crmplan_f095","plan",2,"reg=crime|day=3,30|mood=calm",{1,"We need the church people as customers, they got what we want, we got what they need",2,"What the hell do they need?",1,"Protection, and they don't know it yet",2,"We sell 'em protection from us, I see the business model"}},
{"fw_ld5_crmplan_f096","plan",2,"reg=crime|day=3,30|mood=calm",{1,"Doc Landry, we offer him a deal, protection for medicine",2,"He'll refuse",1,"He'll refuse the first time, then his hip will hurt, then he'll think about it",2,"You're patient, that's what I like about you"}},
{"fw_ld5_jailplan_f097","plan",2,"reg=prison|mood=calm",{1,"Shoes first, nothing else matters if you don't have shoes",2,"I got shoes",1,"Those are prison shoes, they got the stamp, find real ones",2,"...The first house, we'll find shoes, size eleven, I'm a big man"}},
{"fw_ld5_jailplan_f098","plan",2,"reg=prison|mood=funny",{1,"Burn the orange, all of it",2,"It's the only clothes I got",1,"Then burn the fucking orange, and walk around in your underwear, I don't care, just don't walk around in orange",2,"There's a clothesline on that farm, I seen it"}},
{"fw_ld5_jailplan_f099","plan",2,"reg=prison|day=2,30|mood=grim",{1,"Don't-- don't tell 'em how we got out",2,"Why not?",1,"Because then they ask who we left in there, and I don't wanna answer",2,"I'll say we walked, which is true"}},
{"fw_ld5_jailplan_f100","plan",2,"reg=prison|mood=calm",{1,"Nobody needs to hear what you did. Keep it to yourself",2,"What if somebody asks?",1,"Tell 'em the truth: 'It was a long time ago. I'm not that guy now'",2,"I like it, I'm gonna steal it"}},
{"fw_ld5_later_g001","plan",2,"reg=civilian,family,worker,rescue|day=20,200|mood=grim",{1,"Every store inside ten miles is picked clean, I walked all of 'em",2,"So what, we starve?",1,"We go farther, the next county, nobody's been through there",2,"Nobody's been through 'cause it's twenty miles and every mile has a reason not to",1,"I know, I'm just tired of the sound of the can opener",2,"...Pack for three days, and if it's bad we turn around, no arguing"}},
{"fw_ld5_later_g002","plan",2,"reg=family|day=15,200|mood=calm",{1,"We save the seeds from the tomatoes, dry 'em on a paper towel",2,"What for?",1,"Next year, you plant 'em, you get tomatoes, Mamaw's done it since 1950",2,"Next year, God, you're thinking about next year?",1,"Somebody's gotta, if we all think about today we're hungry in the spring",2,"...Fine, I'll dig the beds, you tell me where"}},
{"fw_ld5_later_g003","plan",2,"reg=civilian,family,worker,rescue|day=20,200|mood=sad",{1,"I, I don't even know what day it is anymore",2,"Wednesday, I think",1,"You said Wednesday yesterday",2,"...I don't know, I lost it somewhere around the second week",1,"We make a calendar on the wall, a mark every day, I'm NOT losing the days too",2,"I'll do the marks, you do the names, it's something to do"}},
{"fw_ld5_later_g004","plan",2,"reg=worker|day=15,200|mood=calm",{1,"We dig a well, the creek's getting low, I don't trust it anyway",2,"With what? A shovel?",1,"Post hole digger at the hardware store, and a hand pump, my uncle did it",2,"How deep?",1,"Twenty feet, thirty maybe, a week of work",2,"A week's better than boiling creek water for a year, I'm in"}},
{"fw_ld5_later_g005","plan",2,"reg=civilian,family,worker,rescue|day=15,200|mood=calm",{1,"Somebody's gotta go to the Hollis farm for seed",2,"They won't give it to us",1,"They'll trade, they got more than they need, we got salt",2,"Salt, good, I'll carry",1,"And ask about a pig, I'm dreaming about a pig"}},
{"fw_ld5_later_g006","plan",2,"reg=civilian,family,worker,rescue|day=20,200|mood=calm",{1,"We make the run to the farm every week, same day, same time, so they expect us",2,"Same day makes us a target",1,"Same day means they put the eggs out by the gate for us, Hollis said so himself",2,"...You're thinking like a shopkeeper",1,"I was a shopkeeper twenty years, I know who pays on time"}},
{"fw_ld5_later_g007","plan",2,"reg=civilian,family,worker,rescue|day=25,200|mood=calm",{1,"There's a deer trail behind the church, I seen tracks, big ones",2,"Venison would be a miracle",1,"Rifle's loud, so a bow, I know where there's a bow at the sporting goods",2,"You know how to use one?",1,"No, but a deer don't know that, I got a lot of patience"}},
{"fw_ld5_later_g008","plan",2,"reg=civilian,family,worker,rescue|day=20,200|mood=angry|world=building",{1,"The roof's leaking AGAIN over the kitchen, I'm done putting a bucket under it",2,"Roofing's a job for a roofer",1,"No roofers left, it's us now, so I need tar paper from somewhere",2,"Hardware store, lumber yard, I'll go with you",1,"And somebody to hold the damn ladder"}},
{"fw_ld5_later_g009","plan",2,"reg=worker|day=30,200|mood=calm",{1,"The distribution center in Shepherdsville supplied every grocery in three counties",2,"That's thirty miles",1,"A hundred thousand square feet nobody's touched, I'd bet my goddamn truck",2,"A hundred thousand square feet of whatever's been living in it since July",1,"So we go with a crew, ten guys, guns, it's the only plan I got"}},
{"fw_ld5_later_g010","plan",2,"reg=civilian,family,worker,rescue|day=20,200|mood=sad",{1,"It's been a month, I wanna see the house",2,"There's nothing there, you know that",1,"I know, I just wanna check on the dog",2,"The dog's gone, I'm sorry",1,"I know the dog's gone, I wanna go look anyway",2,"...Okay, day after tomorrow, I'll come with you"}},
{"fw_ld5_later_g011","plan",2,"reg=civilian,family,worker,rescue|day=30,200|mood=grim",{1,"I'm done, I mean it, I can't be the one who decides",2,"Nobody's asking you to be",1,"Everybody's asking me, every morning, every night",2,"So we split it, you do mornings, I do nights, somebody else does the middle",1,"...Somebody else does the middle, I like that"}},
{"fw_ld5_later_g012","plan",2,"reg=civilian,family,worker,rescue|day=25,200|mood=funny",{1,"I'd trade my boots for a cheeseburger",2,"Jesus, don't say that",1,"A REAL one, with the pickles, I'd do things",2,"There's a Hardee's on the damn highway, the grill's probably still there",1,"A Hardee's, you don't understand, that's a church to me"}},
{"fw_ld5_season_g013","plan",2,"reg=civilian,family,worker,rescue|day=40,300|mood=calm|world=autumn",{1,"Leaves are turning, I can smell it, the cold's coming",2,"We got nothing for winter",1,"Coats, boots, blankets, wood, I made a list, it's a long list",2,"Coats first, the Kmart's got a whole rack, we go before the first frost",1,"Before the first frost, I wrote it down"}},
{"fw_ld5_season_g014","plan",2,"reg=civilian,family,worker,rescue|day=60,400|mood=grim|world=winter",{1,"We're burning the chairs, I hate it, but we're burning the chairs",2,"There's a woodlot behind the church, big oaks, down in the storm",1,"We cut it, split it, stack it, I'll teach you, it's the one thing I know",2,"Heavy work, in this cold, on this food",1,"I-- I know, but I'm not freezing to death in a kitchen"}},
{"fw_ld5_season_g015","plan",2,"reg=civilian,family,worker,rescue|day=40,400|mood=angry|world=cold",{1,"It's, it's freezing, I can't feel my toes, we need blankets, now",2,"Motel on the damn highway, a hundred beds, a hundred blankets",1,"It's two miles, in this",2,"Two miles or sit here and freeze, I vote motel",1,"Motel, I'll carry a blanket for you, I'm a good person"}},
{"fw_ld5_season_g016","plan",2,"reg=civilian,family,worker,rescue|day=60,400|mood=calm|world=snow",{1,"Fresh snow, look, tracks everywhere, rabbit, deer, a whole bunch of boots",2,"Boots? Whose boots?",1,"Somebody's been to the barn, we follow the tracks, find out who",2,"Or they find us, snow tells on everybody",1,"So we're careful, slow, we keep the hill behind us"}},
{"fw_ld5_season_g017","plan",2,"reg=civilian,family,worker,rescue|day=20,400|mood=fear|world=storm",{1,"Storm's coming, you see that sky? Green, that's a bad one",2,"Get inside, get EVERYBODY inside",1,"The goddamn truck too, there's a barn",2,"Barn's got a loft, kids go up there, dog, water",1,"Go, go, wind's already picking up"}},
{"fw_ld5_season_g018","plan",2,"reg=civilian,family,worker,rescue|day=20,400|mood=calm|world=wind",{1,"This wind's making me nervous. I'd rather not add a racket of our own",2,"So no shooting today, no hammering, nothing",1,"We stay quiet, we fix what doesn't make noise",2,"Quiet day, I could use one, I'm so tired of loud"}},
{"fw_ld5_season_g019","plan",2,"reg=family|day=100,500|hour=8,18|mood=warm|world=spring",{1,"It's spring, first warm day, I smelled the dirt this morning",2,"We plant today?",1,"Peas, lettuce, the cold stuff, seeds in every hole I find",2,"Every hole, I like that, it's the first hopeful thing I've heard in months"}},
{"fw_ld5_season_g020","plan",2,"reg=civilian,family,worker,rescue|day=100,500|mood=funny|world=summer",{1,"Second summer, and it's hot AGAIN, I forgot how hot",2,"We survived a whole year",1,"Don't say that out loud, you'll jinx us",2,"A whole year, I'm saying it, I'm proud of us",1,"...Fine, a whole year, I'm proud too, don't tell anyone"}},
{"fw_ld5_council_g021","plan",4,"reg=civilian,family,worker,rescue|day=5,200|mood=calm",{1,"Alright everybody, we need a plan, not a fight, a plan",2,"Food's the problem, I say the Kroger",3,"Water's the problem, the creek's drying up",4,"I say we sleep, I'm so tired I could eat the table",1,"Sleep's not a plan, Dale",4,"Best one I heard all day"}},
{"fw_ld5_council_g022","plan",4,"reg=family|mood=funny",{1,"Family meeting, everybody sit, kids too",2,"Do I have to?",3,"What's for supper?",4,"Are we moving again?",1,"We're deciding, one vote each, even Papaw",2,"Papaw votes pie"}},
{"fw_ld5_council_g023","plan",4,"reg=law|day=3,100|mood=grim",{1,"Briefing, everybody, shut up, listen",2,"What the hell's the briefing?",3,"Is there coffee?",4,"I thought we were done briefing",1,"We're never done briefing, sit down, we know nothing, so here's what we do about it"}},
{"fw_ld5_council_g024","plan",4,"reg=military|day=3,100|mood=calm",{1,"Squad, listen up, here's the day",2,"Is it a good day?",3,"It's a day",4,"Just tell us if we're eating",1,"Noon we eat, then we dig, supper if somebody finds supper"}},
{"fw_ld5_council_g025","plan",4,"reg=raider|day=2,60|mood=funny",{1,"Alright, boys, who's got an idea",2,"Pizza",3,"I got a new truck",4,"Don't hit anything this time",1,"Jesus Christ, I asked for ONE idea, that's all I asked for",2,"Pizza's an idea!"}},
{"fw_ld5_lawplan_g026","plan",2,"reg=law|day=1,30|mood=funny",{1,"Unit three, what's your twenty?",2,"Behind the diner, eating",1,"Eating what?",2,"Whatever's in the walk-in that isn't DEAD yet",1,"...Ten-four, save me a plate"}},
{"fw_ld5_milplan_g027","plan",2,"reg=military|day=2,60|mood=funny",{1,"Trade you the crackers for the cheese spread",2,"Cheese spread's the only good thing in the damn bag",1,"Crackers're the only thing that holds the cheese spread",2,"Fine, but I want the jelly too",1,"The jelly's contraband, I need the jelly"}},
{"fw_ld5_crew_g028","plan",2,"reg=raider|day=2,60|mood=angry|world=vehicle",{1,"Hot-wire the Buick, five minutes",2,"It's got a steering lock, damn it",1,"So break the lock, Christ, do I gotta explain EVERYTHING",2,"I'm breaking it, I'm breaking it, you're louder than the lock",1,"Then break it quieter"}},
{"fw_ld5_jailplan_g029","plan",2,"reg=prison|day=3,60|mood=grim",{1,"I, I keep thinking they'll come for us",2,"Who?",1,"Anybody, the law, the guards, somebody with a clipboard",2,"There ain't any clipboards left, man, you're free, act like it",1,"I don't know how, I was inside nine years, I don't know what free does"}},
{"fw_ld5_moment_h001","plan",2,"reg=civilian,family,worker,rescue|x2=m|day=3,100|mood=angry",{1,"You went to the goddamn store ALONE?",2,"It was RIGHT there, two blocks!",1,"Two blocks is how people disappear, Cody, two blocks!",2,"I got the batteries, didn't I? I got the damn batteries",1,"You got lucky, that's what you got, next time somebody goes with you",2,"...Fine, next time you come, but you walk slow, you walk like my grandma"}},
{"fw_ld5_moment_h002","plan",2,"reg=civilian,family,worker,rescue|day=2,60|mood=angry",{1,"Pharmacy, we said the damn pharmacy, we been walking toward it for forty--",2,"I know what we said",1,"So why are we at the church?!",2,"Because the church had a light on, I saw a light, somebody's in there",1,"A light, oh my God, a LIGHT, fine, we check the church, then the pharmacy, don't change it again",2,"I won't, I promise-- I won't"}},
{"fw_ld5_moment_h003","plan",2,"reg=family|day=3,100|mood=sad",{1,"I remember Papaw asking us to leave him behind. Said his knees were done",2,"You weren't going to leave him?",1,"He kept saying we'd cover twice the miles without him",2,"Like that made it an argument you could bear to hear",1,"Said he'd find water and a good chair. Tried to make it sound like a holiday. I hated hearing him bargain with himself"}},
{"fw_ld5_moment_h004","plan",2,"reg=civilian,family,worker,rescue|day=2,60|mood=funny",{1,"Dale says the Army's set up at the Dairy Queen",2,"The Dairy Queen",1,"Out on the bypass, tents, a flag, the whole thing",2,"Dale also said the moon landing was in Arizona",1,"...Yeah, but what if he's right this time? We go, we look, we get ice cream",2,"There's no ice cream, but fine, I'll look at a tent"}},
{"fw_ld5_moment_h005","plan",2,"reg=family|day=2,60|mood=funny",{1,"If a kid wanted to bring a Game Boy, would you let him?",2,"He'd need batteries",1,"Four AAs. I remember that much",2,"Might need those for a flashlight",1,"Might also need him to have something besides being scared",2,"I'd want to know what we actually had before arguing over it. Then I'd ask for a game of Tetris"}},
{"fw_ld5_moment_h006","plan",2,"reg=civilian,family,worker,rescue|day=2,100|mood=sad",{1,"We bury him under the pecan tree, he liked that tree",2,"It's gonna take hours, the ground's like concrete",1,"Then it takes hours, I'm not leaving him on the porch",2,"...I'll get the shovels, you find something to say",1,"I'll say he was a good man, and he hated being called Walter"}},
{"fw_ld5_moment_h007","plan",2,"reg=civilian,family,worker,rescue|day=1,100|mood=angry",{1,"We've passed that damn barn twice",2,"It's a different barn",1,"It's got the same cow, the same dumb cow!",2,"...Okay, we're lost",1,"Say it again, I want everybody to hear it",2,"WE'RE LOST, are you happy? Now look at the map and tell me where the cow is"}},
{"fw_ld5_moment_h008","plan",2,"reg=civilian,family,worker,rescue|day=1,30|hour=8,21|mood=sad",{1,"We, we can't take the dog, he's too loud",2,"He's not loud, he's a good dog",1,"He barked at a squirrel for ten minutes this morning",2,"So I carry him, I put a sock on his nose, I'm not leaving Biscuit",1,"...A sock, God help us, fine, but the second he barks it's you who answers for it"}},
{"fw_ld5_moment_h009","plan",2,"reg=family|day=1,30|mood=funny",{1,"No, we don't need the TV",2,"It was Mama's TV!",1,"It weighs fifty pounds, it doesn't work, we're walking",2,"It's got the little antenna, I just wanna look at it",1,"...Take the antenna, leave the TV, that's the deal, that's the only deal"}},
{"fw_ld5_moment_h010","plan",2,"reg=civilian,family,worker,rescue|day=0,30|mood=fear",{1,"Where are the keys? Where are the keys, where are the goddamn keys?!",2,"In your hand",1,"...They're in my hand",2,"Breathe, you're no good to me dead, breathe, then drive",1,"I'm breathing, I'm breathing, shut up, I'm breathing"}},
{"fw_ld5_moment_h011","plan",2,"reg=civilian,family,worker,rescue|day=5,100|mood=warm",{1,"She's due in two weeks, maybe sooner, she keeps rubbing her back",2,"Where do we have a baby?",1,"Mrs. Doyle said she'd come to the church. Three hundred babies she's delivered. What's going on doesn't make a bit of difference to her",2,"We'll make her a bed at the church. Clean sheets, hot water... I'll find a kettle",1,"And a lot of towels, and don't tell her I said so, but I'm scared to death"}},
{"fw_ld5_moment_h012","plan",2,"reg=civilian,family,worker,rescue|day=2,100|mood=grim",{1,"It's-- it's empty, the whole shelf's empty, somebody got here first",2,"Shit",1,"Yeah",2,"Okay, plan B, what's plan B?",1,"There's no plan B, I thought we'd find something, I never thought past the shelf",2,"...So we make a plan B right now, out here, first thing we don't panic"}},
{"fw_ld5_moment_h013","plan",2,"reg=civilian,family,worker,rescue|day=2,100|mood=calm",{1,"I drew circles on the map in marker, every place we could check",2,"There's twenty circles",1,"Twenty places, we do one a day, cross 'em off so we know we did it",2,"That's three weeks of circles",1,"It's three weeks of something to do, I'm sick of sitting, pick a circle"}},
{"fw_ld5_moment_h014","plan",2,"reg=civilian,family,worker,rescue|day=1,30|mood=fear",{1,"Stop banging the pots, STOP it, I don't want to find out what can hear us",2,"I'm cooking!",1,"You can cook with the lid off, quietly, like a human being",2,"It's, it's a PAN, it makes noise, that's what it does",1,"Then we eat cold, I'd rather eat cold than hear that sound again"}},
{"fw_ld5_moment_h015","plan",2,"reg=civilian,family,worker,rescue|day=2,100|mood=fear",{1,"Gram's oxygen is at a quarter, I checked, she's got two days",2,"Two days, Jesus",1,"There's a medical supply place on the bypass, big green sign, I seen it",2,"We go now, today, I carry the empty tank, you carry the damn bat",1,"If they don't have it we try the hospital, and if they don't have it--",2,"They'll have it, STOP, don't finish that"}},
{"fw_ld5_moment_h016","plan",2,"reg=civilian,family,worker,rescue|day=2,100|mood=grim",{1,"He's out of test strips, I'm guessing at his sugar, that's not safe",2,"The drugstore on Third?",1,"We checked, it's gone, the clinic maybe, they test everybody",2,"So the clinic, early, before the heat, we ask nicely if there's anybody to ask",1,"There won't be anybody, you know that, but fine, we ask"}},
{"fw_ld5_moment_h017","plan",2,"reg=civilian,family,worker,rescue|day=3,100|mood=warm",{1,"The lady at the end of Hill Street's nursing, she heard about the baby",2,"You asked her?",1,"She asked ME, she knocked on the door, said send the baby over when it's time",2,"A stranger knocked and offered milk?",1,"Her name's Opal, she lost two of her own, she says it helps her, I'm not arguing with that"}},
{"fw_ld5_moment_h018","plan",2,"reg=civilian,family,worker,rescue|day=1,60|mood=fear",{1,"He's gone, his bed's empty, his shoes are gone",2,"Where-- where would he go?!",1,"The goddamn school, the creek, Tommy's, I don't KNOW, I don't know!",2,"Think, three of us, three directions, we meet at the church in an hour",1,"If he's NOT there?",2,"He'll be there, he's ten, he's not stupid, go"}},
{"fw_ld5_moment_h019","plan",2,"reg=civilian,family,worker,rescue|day=3,100|mood=calm",{1,"Smoke over the ridge, white, thin, a cook fire I'd say",2,"Somebody's out there",1,"Somebody who's not scared of smoke, or somebody who don't know better",2,"We go look, from the trees, no closer than we have to, if they're good people we say hello",1,"And if they're not, we saw their smoke and they never saw us, that's worth something"}},
{"fw_ld5_moment_h020","plan",2,"reg=civilian,family,worker,rescue|day=3,100|hour=8,23|mood=angry",{1,"Somebody went through the cellar, took the beans, took my mother's canning jars",2,"Who?",1,"I don't KNOW who, but it wasn't them, they don't take canning jars",2,"We hide the rest, tonight, somewhere nobody looks",1,"Somewhere nobody looks, I'm all ears, I'm all out of ideas"}},
{"fw_ld5_moment_h021","plan",2,"reg=civilian,family,worker,rescue|day=3,100|mood=angry",{1,"Why the hell am I carrying the heavy bag?!",2,"Because you're the strongest",1,"Because I don't complain, that's why, nobody ever makes the whiner carry",2,"...Okay, fair, we switch every mile, I'll carry it first",1,"Thank you, and I'll stop whining, I'm starting now, I'm already starting"}},
{"fw_ld5_moment_h022","plan",2,"reg=family|day=3,100|mood=funny",{1,"We should name the place",2,"It's a garage",1,"A garage with a name, the Garage Hilton, Camp Peach, Fort Mamaw",2,"Fort Mamaw! She'll love it, she'll hate it, same thing",1,"Then it's Fort Mamaw, I'll paint it on the door"}},
{"fw_ld5_moment_h023","plan",2,"reg=civilian,family,worker,rescue|day=2,100|hour=17,20|mood=calm",{1,"Church bell used to ring at six, for supper, I miss that",2,"We can't ring it",1,"I know, I just miss it, I wish somebody would",2,"...I'll tap the radiator at six tomorrow with a spoon, it's not a bell but it's something"}},
{"fw_ld5_moment_h024","plan",2,"reg=civilian,family,worker,rescue|day=2,100|hour=22,5|mood=angry",{1,"You were asleep, I saw you, your chin was on your chest",2,"I was resting my eyes",1,"RESTING YOUR EYES, there's a whole street out there--",2,"...I fell asleep, I'm sorry, I'm SO sorry, it won't happen again",1,"It better not, next time I might not be the one who wakes up"}},
{"fw_ld5_moment_h025","plan",2,"reg=civilian,family,worker,rescue|day=2,100|mood=fear",{1,"I thought I heard a voice on a radio once. Held my breath trying to catch it",2,"What did it say?",1,"Static, then maybe Louisville. I couldn't be sure",2,"Did you try to find it again?",1,"For hours. Wanting to hear it didn't make the words any clearer"}},
{"fw_ld5_moment_h026","plan",2,"reg=civilian,family,worker,rescue|day=0,14|mood=fear",{1,"I can't go out there",2,"You can",1,"I CAN'T, I'm sorry, I can't, I can't make my legs do it",2,"Look at me, only me, it's twelve steps to the truck, I counted",1,"Twelve?!",2,"Twelve, I'll count 'em out loud, you just walk, one, two, three"}},
{"fw_ld5_moment_h027","plan",2,"reg=civilian,family,worker,rescue|day=1,60|hour=3,6|mood=angry",{1,"Why are we up at four in the goddamn morning?",2,"Because nobody's out there at four",1,"Nobody's out there at noon either, we're in the middle of nowhere!",2,"Four's quieter, I don't wanna argue about it, get your goddamn boots",1,"...My feet hurt already and I'm not even standing yet"}},
{"fw_ld5_moment_h028","plan",2,"reg=civilian,family,worker,rescue|day=1,30|mood=fear",{1,"Everybody arms up, I need to see your arms, all of you",2,"Are you serious?",1,"Completely, nobody moves till I've seen every arm, every leg, every neck",2,"...Fine, fine, look, there's nothing, you happy now?!",1,"No, but I'm less scared, and that's as close as it gets, go"}},
{"fw_ld5_moment_h029","plan",2,"reg=family|day=2,60|mood=sad",{1,"Mama's recipe book's still on the shelf",2,"It's a book, we can't carry books",1,"It's forty years of Mama's handwriting, I'm getting it",2,"...It weighs two pounds, I'll carry it, you're right, I'm sorry",1,"I'll go get it, it's four minutes, and I'm going, I'm not asking"}},
{"fw_ld5_moment_h030","plan",2,"reg=civilian,family,worker,rescue|day=1,60|mood=funny",{1,"I gotta pee",2,"We just stopped, you went ten minutes ago",1,"I know when I went. I get scared, I need to go again",2,"Go behind that bush, then. Hurry up. And no screaming over a spider",1,"Spider! There's a spider - no, I'm coming back!"}},
{"fw_ld5_moment_h031","plan",2,"reg=civilian,family,worker,rescue|day=3,60|mood=grim",{1,"If your feet start hurting, don't hide it just to keep us moving",2,"I don't like holding people up",1,"I know. But I can't tell how bad it is from you saying fine",2,"Feels silly making a fuss over a blister",1,"Asking for a rest isn't making a fuss. And I shouldn't promise bandages before checking"}},
{"fw_ld5_moment_h032","plan",2,"reg=civilian,family,worker,rescue|day=1,30|mood=fear",{1,"One, two, three, four, five, six",2,"What the hell are you doing?!",1,"Counting heads, there's supposed to be seven",2,"Seven, it's seven, Danny's behind the tree",1,"...Danny, say something, Danny",2,"Don't do that to me AGAIN, I'm having a heart attack"}},
{"fw_ld5_moment_h033","plan",2,"reg=civilian,family,worker,rescue|day=1,60|mood=warm",{1,"Before we go, can we pray? Just a minute, everybody",2,"I'm not really--",1,"I know, you don't have to, just stand with us, hold a hand",2,"...A minute, one minute, I'm gonna feel stupid",1,"You won't, nobody does, bow your head or look at your shoes, either way is fine"}},
{"fw_ld5_moment_h034","plan",2,"reg=civilian,family,worker,rescue|day=2,100|hour=6,19|mood=calm",{1,"Moss grows on the north side of the trees, everybody knows that",2,"Moss grows on every side, ask my uncle, he got lost for two days",1,"Then we use the sun, east to west, we go north, I'm sure about north",2,"You're sure about north? You were sure about the barn",1,"I'm sure about NORTH, the barn was a one-time thing"}},
{"fw_ld5_moment_h035","plan",2,"reg=civilian,family,worker,rescue|day=2,100|mood=funny",{1,"What the hell's the plan, boss?",2,"Don't call me boss",1,"Plan, boss?",2,"I said don't-- the plan's the Kroger, now STOP it",1,"The Kroger, boss, yes, boss, right away, boss"}},
{"fw_ld5_moment_h036","plan",2,"reg=civilian,family,worker,rescue|day=1,60|mood=angry",{1,"You left the gate open, I told you, I TOLD you",2,"I closed it",1,"You closed it like a person who doesn't care if it stays closed",2,"What's that supposed to mean?!",1,"It means go back, latch it, don't come back until you hear it click"}},
{"fw_ld5_moment_h037","plan",2,"reg=civilian,family,worker,rescue|day=2,100|mood=sad",{1,"I can't stop thinking about the last thing she said",2,"Don't",1,"She said pick up milk, that was it, pick up milk on the way home",2,"I know, I know you've said",1,"I'm going to the Kroger and I'm getting milk, I don't care if it's gone, I'm going to stand in that aisle"}},
{"fw_ld5_moment_h038","plan",2,"reg=civilian,family,worker,rescue|day=2,100|mood=funny",{1,"Rock, paper, scissors, loser checks the--",2,"No",1,"Rock, paper, scissors, come on, it's fair",2,"I always lose, I lost last time, I lost the time before that",1,"So you're due, that's how luck works, throw"}},
{"fw_ld5_moment_h039","plan",2,"reg=law|day=1,30|mood=sad",{1,"You're shaking",2,"I'm fine",1,"You're not fine, you're twenty-three, you've been on the job a year, you're shaking",2,"...What do I do if it's somebody I know?",1,"You do what I do, you say their name, quietly, you do the job"}},
{"fw_ld5_moment_h040","plan",2,"reg=law|day=1,30|mood=sad",{1,"Play it again, the last dispatch",2,"We've played it fifty times",1,"I know, I just wanna hear her voice, play it",2,"...All units, be advised, all units, be-- then nothing",1,"One more time, then we go to the school, I won't ask again"}},
{"fw_ld5_moment_h041","plan",2,"reg=law,swat|day=1,30|mood=fear",{1,"I-- I need to check the school",2,"You keep thinking about it",1,"My daughter's at the school, I mean, she was, Friday, I don't know",2,"I can't tell you where she is. But you don't have to carry the worry without talking to somebody",1,"I keep wanting to promise I'll find her. I can't even promise when I'd be back"}},
{"fw_ld5_moment_h042","plan",2,"reg=military|day=2,60|hour=8,22|mood=calm",{1,"Chaplain's gonna say a few words tonight, you coming?",2,"I'm not religious",1,"Nobody's asking you to be, it's twenty minutes, it's quiet, there's coffee",2,"There's coffee?",1,"Real coffee, he's been hiding it, that's the real reason half of us go"}},
{"fw_ld5_moment_h043","plan",2,"reg=military|day=2,60|mood=funny",{1,"Rumor is the Army's got a camp in Indiana",2,"Yeah, and the moon landing was filmed in Nevada if you ask the right idiot",1,"This one's from a guy who talked to a guy who saw a convoy",2,"A guy who talked to a guy, that's the best evidence we've had in a week",1,"We go, we look, I'd rather chase a rumor than sit on a hill"}},
{"fw_ld5_moment_h044","plan",2,"reg=military|day=2,60|mood=grim",{1,"If you're carrying a rifle, don't forget to check its condition before a trip",2,"Even if I cleaned it yesterday?",1,"I'd rather check than assume. But knowing it's clean wouldn't make the whole trip safe",2,"No. Just one thing to think about before moving"}},
{"fw_ld5_crew_h045","plan",2,"reg=raider|day=2,60|mood=angry",{1,"If we ever have a truck to load, can we get through it without fighting?",2,"He'd start it",1,"I don't give a shit who'd start it. I'd like one job finished without an argument",2,"Then I'd wait till we were finished",1,"That's not what I meant, you asshole. Nobody gets a turn to hit somebody after"}},
{"fw_ld5_crew_h046","plan",2,"reg=raider|day=3,60|mood=funny",{1,"New guy, you ever shoot anything?",2,"Deer, mostly",1,"Deer, great, we'll put you at the front, they'll love it",2,"I don't think that's how that works",1,"It's how it works if I say it works, welcome to the crew, don't die"}},
{"fw_ld5_crew_h047","plan",2,"reg=raider|day=2,60|hour=8,23|mood=grim",{1,"Where the hell's the stash?",2,"Under the floor, same as always",1,"Somebody's been in it, I can tell, the boards are wrong",2,"Nobody knows where it is",1,"Somebody knows, and I'm gonna find out who, we move it tonight"}},
{"fw_ld5_gangplan_h048","plan",2,"reg=gang|day=2,60|mood=funny",{1,"What if we asked the church people for a blessing?",2,"For what?",1,"For the plan, for luck, for the next job, I don't know, it can't hurt",2,"It can hurt, they'll ask what the plan is, then what do we say",1,"We say it's a surprise, shit, I'll say it, I'm good at lying to preachers"}},
{"fw_ld5_jailplan_h049","plan",2,"reg=prison|day=2,60|hour=21,5|mood=grim",{1,"Hey, you awake?",2,"Yeah",1,"Can't sleep either, every sound, I keep thinking it's the count",2,"There's no count, there's no CO, there's nobody",1,"Fuck, I know, my head don't, it thinks it's four in the morning, lights about to come on",2,"Then we're up and gone before the lights, come on, we move at first gray"}},
{"fw_ld5_clubplan_h050","plan",2,"reg=club|day=2,60|mood=calm",{1,"You ever think about what happens after?",2,"After what?",1,"After the fucking gas runs out, the bikes die, all of it",2,"I think we walk, brother, till we find somewhere to stay, then we stay",1,"And the club?",2,"Then the club's the six of us, prospect included, God help it"}},
{"fw_ld5_crmplan_h051","plan",2,"reg=crime|day=3,60|mood=calm",{1,"Mr. D says we start taxing the church for protection",2,"The church won't pay",1,"They'll pay if they're scared, and they're scared, so they'll pay",2,"I don't like it",1,"I didn't ask if you liked it, I said what Mr. D said"}},
{"fw_ld5_milplan_h052","plan",2,"reg=military|day=2,60|mood=sad",{1,"You think my wife's okay?",2,"I think she's smart, I think she locked the door",1,"She'd lock the door, she's smarter than me",2,"Then she's okay, that's what I'd tell myself, you should too",1,"...I'm telling myself, and when we get to the bridge I'm asking every convoy about her"}},
{"fw_ld5_wrklaw_i001","plan",2,"r1=worker|r2=law,swat|day=1,20|mood=calm",{1,"Water plant's got a diesel generator and I got the key, somebody's gotta babysit it",2,"How many hours a day?",1,"Eight keeps the tower full, I did the math on a napkin",2,"I'll ride you out at six and sit on the gate while you pump"}},
{"fw_ld5_wrklaw_i002","plan",2,"r1=worker|r2=law,swat|day=0,10|mood=fear",{1,"I got a rig at the weigh station, full tank, forty-foot flatbed",2,"You wanna drive out of here",1,"I wanna drive somebody out, I ain't leaving with an empty trailer",2,"Then we fill it, the church folks first, I ride shotgun, you pick the road"}},
{"fw_ld5_wrklaw_i003","plan",2,"r1=worker|r2=law,swat|day=1,14|mood=calm",{1,"I can climb a pole and see which line's dead, an hour, tops",2,"What's that buy us?",1,"If the substation's alive I can feed the school, the well pump alone's worth it",2,"Then the substation first, I hold the ladder, nobody climbs alone"}},
{"fw_ld5_wrklaw_i004","plan",2,"r1=worker|r2=law,swat|day=2,30|mood=grim",{1,"Your cruiser's dying, officer, that whine's the fuel pump",2,"Can you swap it?",1,"Auto parts on Dixie had a dozen on the wall last time I looked",2,"Then we go there first, I'm not driving into the next county on a whine"}},
{"fw_ld5_wrklaw_i005","plan",2,"r1=worker|r2=law,swat|day=0,8|hour=7,19|mood=fear",{1,"My cattle got out on Sixty, thirty head, they'll walk right into the road",2,"Cows are the last thing I'm worried about",1,"They're all I got, I gotta pen 'em before dark",2,"...Fine, I block the road with the cruiser, you run, I'll wave off anything that comes"}},
{"fw_ld5_wrklaw_i006","plan",2,"r1=worker|r2=law,swat|day=1,14|mood=warm",{1,"I can feed thirty at the courthouse if somebody finds me a stove",2,"Feed 'em what?",1,"Rice, canned chili, whatever the Kroger left, I'll make it stretch",2,"There's a camp stove in the evidence locker, I'll sign it out to you"}},
{"fw_ld5_wrklaw_i007","plan",2,"r1=worker|r2=law,swat|day=2,30|hour=5,12|mood=calm",{1,"Our warehouse got four pallets of bottled water nobody's touched",2,"How far?",1,"Six blocks, the forklift wants gas, somebody who knows the clutch",2,"You're the somebody, I'm the one with the shotgun, we go before the heat"}},
{"fw_ld5_wrklaw_i008","plan",2,"r1=worker|r2=law,swat|day=1,10|mood=fear",{1,"I got a dozer at the quarry, I could close the bridge in an hour",2,"Close it with what?",1,"Concrete barriers off the quarry road, and a dump truck for the gap",2,"Then do it, I'll stand at the east end and turn people around, I hate it already"}},
{"fw_ld5_wrklaw_i009","plan",2,"r1=worker|r2=law,swat|day=0,10|mood=angry",{1,"Co-op's got a bulk tank of diesel, four hundred gallons, pump's dead",2,"So we're stuck",1,"We're not stuck, I climb up, open the valve by hand, gravity does the rest",2,"Then climb, I'll watch the lot, don't spill any on my boots"}},
{"fw_ld5_wrklaw_i010","plan",2,"r1=worker|r2=law,swat|day=0,12|mood=calm",{1,"I got every key to the high school, thirty years of carrying 'em",2,"Boiler room too?",1,"Boiler room, gym, the principal's office, he kept a bottle in the desk",2,"Then you open the gym and the desk, I'll count the cots, look the other way"}},
{"fw_ld5_wrklaw_i011","plan",2,"r1=worker|r2=law,swat|day=1,14|mood=sad",{1,"Route four, I drove it eleven years, I know every kid who rides it",2,"You wanna check the stops",1,"I wanna know who's still standing at one, even if it's nobody",2,"Then we drive it, you in the seat, me watching the windows, one loop, no heroics"}},
{"fw_ld5_wrklaw_i012","plan",2,"r1=worker|r2=law,swat|day=3,40|mood=funny",{1,"Grain elevator's got tons of corn, I ran the scale there nine years",2,"Corn's for horses",1,"It's people food if somebody grinds it, there's a hand mill in the museum on the square",2,"In a glass case with a little card, I'll break the glass, apologize to the card"}},
{"fw_ld5_lawwrk_i013","plan",2,"r1=law,swat|r2=worker|day=2,30|mood=calm",{1,"You still got the fairgrounds keys, Hap?",2,"Every gate, the livestock barn too, why?",1,"Livestock barn's got a roof and a spigot, and the stalls have doors",2,"Doors, I like that, we bed the old folks down in clean straw, I bring blankets"}},
{"fw_ld5_lawwrk_i014","plan",2,"r1=law,swat|r2=worker|day=1,14|mood=fear",{1,"Where's the safest place in the plant, you know it better than me",2,"Not the chlorine room, steel door, one way in, I wouldn't sit in there for money",1,"Why not?",2,"Chlorine, officer, that gas'll kill you quicker than anything out there, pick the loading dock"}},
{"fw_ld5_lawwrk_i015","plan",2,"r1=law,swat|r2=worker|day=2,20|hour=3,9|mood=funny",{1,"What's the one thing you'd carry out of the plant?",2,"The coffee maker, it's industrial, makes sixty cups",1,"Sixty cups, I'd carry it myself",2,"Then we go at dawn, it weighs a hundred pounds, you're on the left handle"}},
{"fw_ld5_wrkmil_i016","plan",2,"r1=worker|r2=military|day=1,20|mood=calm",{1,"Your Humvee's choking, soldier, sounds like the fuel filter to me",2,"Can you fix it?",1,"I can swap one if there's a parts house that ain't been hit, Dixie's got two",2,"Then we drive on fumes to Dixie, I push the last half mile if I gotta"}},
{"fw_ld5_wrkmil_i017","plan",2,"r1=worker|r2=military|day=1,14|mood=calm",{1,"I drove this route twenty years, you want a quiet way to Knox, follow my rig",2,"Why you?",1,"I know which bridges hold a loaded truck, and the map don't say",2,"Then you lead, I ride behind, one flash of the lights means stop"}},
}
